// @FIGURE_CODE_BEGIN
// x-axis -> Line from (0,0,0) to (9.5,0,0) with Cone at the end, black
// true surface -> PlaneGeometry(6, 3, 60, 30) translucent pink mesh with depthWrite false
// slabs -> ExtrudeGeometry along X axis of a custom Shape in YZ plane, pink/blue, EdgesGeometry black
// thick outline -> Cylinders forming the perimeter of the active slab's -x face, black
// callout arrow -> Cylinder + Cone pointing rightwards, orange
// bracket -> Line tracing a dimension bracket |___| below the active slab
// xk dot -> small SphereGeometry on the axis

const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.6);
dirLight.position.set(5, 12, 15);
scene.add(dirLight);

// Base Axis
const axisGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(9.5, 0, 0)
]);
const axisLine = new THREE.Line(axisGeom, new THREE.LineBasicMaterial({ color: 0x000000 }));
scene.add(axisLine);
const arrowGeom = new THREE.ConeGeometry(0.12, 0.4, 16);
const arrowMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const arrow = new THREE.Mesh(arrowGeom, arrowMat);
arrow.position.set(9.6, 0, 0);
arrow.rotation.z = -Math.PI / 2;
scene.add(arrow);

// True Continuous Surface
const trueSurfGeom = new THREE.PlaneGeometry(6, 3, 60, 30);
const tsPos = trueSurfGeom.attributes.position;
for (let i = 0; i < tsPos.count; i++) {
  const u = tsPos.getX(i);
  const v = tsPos.getY(i);
  const x = u + 5;
  const z = v;
  const y = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * x) - 0.1 * z * z;
  tsPos.setXYZ(i, x, y, z);
}
trueSurfGeom.computeVertexNormals();
const trueSurfMat = new THREE.MeshLambertMaterial({
  color: 0xffaaaa,
  transparent: true,
  opacity: 0.3,
  side: THREE.DoubleSide,
  depthWrite: false
});
const trueSurface = new THREE.Mesh(trueSurfGeom, trueSurfMat);
scene.add(trueSurface);

// Materials for dynamically generated elements
const meshMaterialPink = new THREE.MeshLambertMaterial({ color: 0xffcccc, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const meshMaterialBlue = new THREE.MeshLambertMaterial({ color: 0xaaccff, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const edgeMaterial = new THREE.LineBasicMaterial({ color: 0x000000 });
const thickEdgeMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });

// Slab generation function
function createSlab(x_start, x_end, x_mid, isBlue) {
  const shape = new THREE.Shape();
  shape.moveTo(1.5, 0);
  for (let i = 20; i >= 0; i--) {
    const z_form = -1.5 + 3.0 * i / 20;
    const height = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * x_mid) - 0.1 * z_form * z_form;
    shape.lineTo(z_form, height);
  }
  shape.lineTo(-1.5, 0);
  shape.closePath();

  const geom = new THREE.ExtrudeGeometry(shape, { depth: x_end - x_start, bevelEnabled: false });
  const pos = geom.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const lx = pos.getX(i);
    const ly = pos.getY(i);
    const lz = pos.getZ(i);
    pos.setXYZ(i, lz + x_start, ly, lx);
  }
  geom.computeVertexNormals();

  const mesh = new THREE.Mesh(geom, isBlue ? meshMaterialBlue : meshMaterialPink);
  const edgesGeom = new THREE.EdgesGeometry(geom);
  const edges = new THREE.LineSegments(edgesGeom, edgeMaterial);
  mesh.add(edges);

  mesh.userData.dispose = () => {
    geom.dispose();
    edgesGeom.dispose();
  };
  return mesh;
}

// Emphasized face outline function
function createThickOutline(x_start, x_mid) {
  const pts = [];
  pts.push(new THREE.Vector3(x_start, 0, 1.5));
  for (let i = 20; i >= 0; i--) {
    const z_form = -1.5 + 3.0 * i / 20;
    const height = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * x_mid) - 0.1 * z_form * z_form;
    pts.push(new THREE.Vector3(x_start, height, z_form));
  }
  pts.push(new THREE.Vector3(x_start, 0, -1.5));
  pts.push(new THREE.Vector3(x_start, 0, 1.5));

  const group = new THREE.Group();
  for (let i = 0; i < pts.length - 1; i++) {
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const dist = p1.distanceTo(p2);
    const geom = new THREE.CylinderGeometry(0.025, 0.025, dist, 6);
    const mesh = new THREE.Mesh(geom, thickEdgeMaterial);
    mesh.position.copy(p1).lerp(p2, 0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), p2.clone().sub(p1).normalize());
    group.add(mesh);
    mesh.userData.geom = geom;
  }
  group.userData.dispose = () => {
    group.children.forEach(c => {
      if (c.userData.geom) c.userData.geom.dispose();
    });
  };
  return group;
}

// Groups and persistent elements for active slice display
const slabsGroup = new THREE.Group();
scene.add(slabsGroup);
const thickOutlineGroup = new THREE.Group();
scene.add(thickOutlineGroup);

const dimGroup = new THREE.Group();
const dimGeom = new THREE.BufferGeometry();
const dimLine = new THREE.Line(dimGeom, edgeMaterial);
dimGroup.add(dimLine);
scene.add(dimGroup);

const dotGeom = new THREE.SphereGeometry(0.06, 16, 16);
const dotMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const xkDot = new THREE.Mesh(dotGeom, dotMat);
scene.add(xkDot);

const calloutArrowGeom = new THREE.CylinderGeometry(0.02, 0.02, 1.0, 8);
const calloutArrowHead = new THREE.ConeGeometry(0.08, 0.2, 16);
const calloutArrowMat = new THREE.MeshLambertMaterial({ color: 0xffa500 });
const calloutArrowGroup = new THREE.Group();
const cCyl = new THREE.Mesh(calloutArrowGeom, calloutArrowMat);
cCyl.position.set(-0.5, 0, 0);
cCyl.rotation.z = Math.PI / 2;
const cHead = new THREE.Mesh(calloutArrowHead, calloutArrowMat);
cHead.position.set(0, 0, 0);
cHead.rotation.z = -Math.PI / 2;
calloutArrowGroup.add(cCyl);
calloutArrowGroup.add(cHead);
scene.add(calloutArrowGroup);

// Labels
addLabel('<i>a</i>', new THREE.Vector3(2, -0.3, 0));
addLabel('<i>b</i>', new THREE.Vector3(8, -0.3, 0));
addLabel('<i>x</i>', new THREE.Vector3(9.5, -0.3, 0));

const label_S1 = addLabel('<i>S</i><sub>1</sub>', new THREE.Vector3(0, 0, 0));
const label_S2 = addLabel('<i>S</i><sub>2</sub>', new THREE.Vector3(0, 0, 0));
const label_Sn = addLabel('<i>S</i><sub>n</sub>', new THREE.Vector3(0, 0, 0));
const label_xk = addLabel('<i>x<sub>k</sub></i><sup>*</sup>', new THREE.Vector3(0, 0, 0), { offset: [0, 15] });
const label_dxk = addLabel('&Delta;<i>x<sub>k</sub></i>', new THREE.Vector3(0, 0, 0), { offset: [0, 12] });

const calloutHtmlStr = `
<div style="background: #ffeb99; border: 1px solid #dcb; padding: 5px 10px; border-radius: 6px; text-align: center; color: #111; font-size: 13px;">
  The cross<br>section here<br>has area<br><i>A</i>(<i>x<sub>k</sub></i><sup>*</sup>).
</div>
`;
const label_callout = addLabel(calloutHtmlStr, new THREE.Vector3(0, 0, 0));

// Logic update
function updateFigure() {
  const n = parseInt(document.getElementById('numSlabs').value);
  let pos = parseFloat(document.getElementById('slicePosition').value);
  const viewStr = document.getElementById('view').value || 'Full Solid';
  const isIsolated = viewStr === 'Isolated Slab';

  if (pos < 2) pos = 2;
  if (pos > 8) pos = 8;

  const dx = 6 / n;
  let k = Math.floor((pos - 2) / dx);
  if (k >= n) k = n - 1;

  while (slabsGroup.children.length > 0) {
    const child = slabsGroup.children[0];
    slabsGroup.remove(child);
    if (child.userData.dispose) child.userData.dispose();
  }
  while (thickOutlineGroup.children.length > 0) {
    const child = thickOutlineGroup.children[0];
    thickOutlineGroup.remove(child);
    if (child.userData.dispose) child.userData.dispose();
  }

  trueSurface.visible = !isIsolated;
  dimGroup.visible = isIsolated;
  calloutArrowGroup.visible = isIsolated;
  label_callout.div.style.display = isIsolated ? '' : 'none';
  label_dxk.div.style.display = isIsolated ? '' : 'none';
  xkDot.visible = true;

  for (let i = 0; i < n; i++) {
    const x_start = 2 + i * dx;
    const x_end = 2 + (i + 1) * dx;
    const x_mid = (x_start + x_end) / 2;
    const isBlue = (i === k);

    if (isIsolated && !isBlue) continue;

    const slab = createSlab(x_start, x_end, x_mid, isBlue);
    slabsGroup.add(slab);

    if (isBlue) {
      const active_height = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * x_mid);

      const thickOutline = createThickOutline(x_start, x_mid);
      thickOutlineGroup.add(thickOutline);

      xkDot.position.set(x_mid, 0, 0);
      label_xk.pos.set(x_mid, -0.15, 0);

      if (isIsolated) {
        dimGeom.setFromPoints([
          new THREE.Vector3(x_start, -0.05, 0),
          new THREE.Vector3(x_start, -0.6, 0),
          new THREE.Vector3(x_start, -0.5, 0),
          new THREE.Vector3(x_end, -0.5, 0),
          new THREE.Vector3(x_end, -0.6, 0),
          new THREE.Vector3(x_end, -0.05, 0)
        ]);
        label_dxk.pos.set(x_mid, -0.5, 0);

        calloutArrowGroup.position.set(x_start, active_height * 0.45, 1.5);
        label_callout.pos.set(x_start - 1.15, active_height * 0.45, 1.5);
      }
    }
  }

  if (!isIsolated && n <= 16) {
    label_S1.div.style.display = '';
    label_S2.div.style.display = '';
    label_Sn.div.style.display = '';

    const h1 = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * (2 + dx/2));
    label_S1.pos.set(2 + dx/2, h1/2, 1.55);

    const h2 = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * (2 + 1.5*dx));
    label_S2.pos.set(2 + 1.5*dx, h2/2, 1.55);

    const hn = 2.0 + 0.3 * Math.sin(1.0 + 0.5 * (2 + (n-0.5)*dx));
    label_Sn.pos.set(2 + (n-0.5)*dx, hn/2, 1.55);
  } else {
    label_S1.div.style.display = 'none';
    label_S2.div.style.display = 'none';
    label_Sn.div.style.display = 'none';
  }
}

document.getElementById('numSlabs').addEventListener('input', updateFigure);
document.getElementById('slicePosition').addEventListener('input', updateFigure);
document.getElementById('view').addEventListener('change', updateFigure);

function setActiveBtn(id) {
  ['btnStep1', 'btnStep2', 'btnStep3'].forEach(b => {
    document.getElementById(b).classList.remove('active');
  });
  document.getElementById(id).classList.add('active');
}

document.getElementById('btnStep1').addEventListener('click', () => {
