});
document.getElementById('btnStep2').addEventListener('click', () => {
  document.getElementById('numSlabs').value = 6;
  document.getElementById('slicePosition').value = 3.5;
  document.getElementById('view').value = 'Isolated Slab';
  updateFigure();
  setActiveBtn('btnStep2');
});
document.getElementById('btnStep3').addEventListener('click', () => {
  document.getElementById('numSlabs').value = 24;
  document.getElementById('slicePosition').value = 5;
  document.getElementById('view').value = 'Full Solid';
  updateFigure();
