Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  Number of slabs (n)
  <input type="range" id="numSlabs" min="4" max="30" step="1" value="6">
</label>
<label>
  Slice position x
  <input type="range" id="slicePosition" min="2" max="8" step="0.1" value="4.5">
</label>
<div style="margin-top: 6px;">
  <label style="margin-bottom: 2px;">View</label>
  <select id="view" style="width: 100%; padding: 3px;">
    <option value="Full Solid">Full Solid</option>
    <option value="Isolated Slab">Isolated Slab</option>
  </select>
</div>
<div style="margin-top: 12px; font-weight: bold;">Demo Steps:</div>
<button id="btnStep1" class="active">Coarse partition</button>
<button id="btnStep2">Examine a single slab</button>
<button id="btnStep3">Finer partition</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// axis lines -> THREE.Line (black) with ConeGeometry at the end
// slabs -> ExtrudeGeometry along Z, drawn by tracing f(x) in XY plane, extruded to D. Scaled to recede in Z.
// boundaries -> THREE.Line tracing only the visible slab boundaries, no wireframe clutter
// isolated cross-section -> PlaneGeometry with slightly transparent material + thick Cylinder borders
// callout arrow -> Cylinder + Cone (orange/yellowish)
// bracket -> THREE.Line for the dimension bracket below the isolated slab
// labels -> HTML floating labels managed via pos.set(0,-1000,0) to hide them safely

const D = 2.5; // Depth of the solid
const a = 2.0;
const b = 8.0;

function f(x) {
    return 1.5 + 0.4 * x - 0.02 * x * x;
}

// Colors
const colorPink = 0xffdada;
const colorBlue = 0xaad0ff;
const colorLine = 0x000000;

// Materials
const matPink = new THREE.MeshLambertMaterial({ color: colorPink, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const matBlue = new THREE.MeshLambertMaterial({ color: colorBlue, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const matCrossSection = new THREE.MeshBasicMaterial({ color: 0x88bbff, transparent: true, opacity: 0.5, side: THREE.DoubleSide });
const lineMat = new THREE.LineBasicMaterial({ color: colorLine });

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.75);
scene.add(ambientLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.45);
dirLight.position.set(2, 8, 10);
scene.add(dirLight);

// Groups
const slabsGroup = new THREE.Group();
scene.add(slabsGroup);
const linesGroup = new THREE.Group();
scene.add(linesGroup);
const isolatedGroup = new THREE.Group();
scene.add(isolatedGroup);
const ticksGroup = new THREE.Group();
scene.add(ticksGroup);

// Axis
const axisGeom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.5, 0, 0),
    new THREE.Vector3(10, 0, 0)
]);
const axisLine = new THREE.Line(axisGeom, lineMat);
scene.add(axisLine);
const arrowGeom = new THREE.ConeGeometry(0.12, 0.4, 16);
const arrow = new THREE.Mesh(arrowGeom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
arrow.position.set(10, 0, 0);
arrow.rotation.z = -Math.PI / 2;
scene.add(arrow);

// Bracket for isolated view
const bracketGroup = new THREE.Group();
const v1 = new THREE.Line(new THREE.BufferGeometry(), lineMat);
const v2 = new THREE.Line(new THREE.BufferGeometry(), lineMat);
const hBracket = new THREE.Line(new THREE.BufferGeometry(), lineMat);
bracketGroup.add(v1);
bracketGroup.add(v2);
bracketGroup.add(hBracket);
scene.add(bracketGroup);

// Callout Arrow
const calloutArrowMat = new THREE.MeshBasicMaterial({ color: 0xffcc99 });
const arrG = new THREE.Group();
const arrCyl = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 1.2), calloutArrowMat);
arrCyl.rotation.z = Math.PI/2;
arrCyl.position.x = -0.6;
const arrCone = new THREE.Mesh(new THREE.ConeGeometry(0.15, 0.4), calloutArrowMat);
arrCone.rotation.z = -Math.PI/2;
arrG.add(arrCyl);
arrG.add(arrCone);
scene.add(arrG);

// Labels
const lbl_a = addLabel('<i>a</i>', new THREE.Vector3(0,0,0));
const lbl_b = addLabel('<i>b</i>', new THREE.Vector3(0,0,0));
const lbl_x = addLabel('<i>x</i>', new THREE.Vector3(10, -0.4, 0));

const tickLabels = [];
for(let i=0; i<10; i++) {
    tickLabels.push(addLabel('', new THREE.Vector3(0,0,0)));
}

const lbl_S1 = addLabel('<span style="font-size: 16px;"><i>S</i><sub>1</sub></span>', new THREE.Vector3(0,0,0));
const lbl_S2 = addLabel('<span style="font-size: 16px;"><i>S</i><sub>2</sub></span>', new THREE.Vector3(0,0,0));
const lbl_Sn = addLabel('<span style="font-size: 16px;"><i>S</i><sub>n</sub></span>', new THREE.Vector3(0,0,0));
const lbl_S = addLabel('<span style="font-size: 18px;"><i>S</i></span>', new THREE.Vector3(0,0,0));

const lbl_xk = addLabel('<i>x<sub>k</sub></i><sup>*</sup>', new THREE.Vector3(0,0,0), { offset: [0, 15] });
const lbl_dxk = addLabel('&Delta;<i>x<sub>k</sub></i>', new THREE.Vector3(0,0,0), { offset: [0, 15] });

const calloutHtml = `
<div style="background: #ffebcc; border: 1px solid #dcb; padding: 6px 12px; border-radius: 8px; text-align: center; color: #111; font-size: 13px; box-shadow: 2px 2px 5px rgba(0,0,0,0.2);">
  The cross<br>section here<br>has area<br><i>A</i>(<i>x<sub>k</sub></i><sup>*</sup>).
</div>
`;
const lbl_callout = addLabel(calloutHtml, new THREE.Vector3(0,0,0));

function disposeGroup(group) {
    const children = [...group.children];
    for (const c of children) {
        if (c.isMesh || c.isLine) {
            if (c.geometry) c.geometry.dispose();
            if (c.material) {
                if (Array.isArray(c.material)) c.material.forEach(m => m.dispose());
                else c.material.dispose();
            }
        }
        if (c.children.length > 0) disposeGroup(c);
        group.remove(c);
    }
}

function createSlab(x_start, x_end, isBlue) {
    const shape = new THREE.Shape();
    shape.moveTo(x_start, 0);
    shape.lineTo(x_end, 0);
    shape.lineTo(x_end, f(x_end));
    const steps = Math.ceil((x_end - x_start) * 10);
    for(let i=1; i<=steps; i++) {
        const x = x_end - (i/steps)*(x_end - x_start);
        shape.lineTo(x, f(x));
    }
    shape.lineTo(x_start, 0);

    const geom = new THREE.ExtrudeGeometry(shape, { depth: D, bevelEnabled: false });
    const mesh = new THREE.Mesh(geom, isBlue ? matBlue : matPink);
    mesh.scale.set(1, 1, -1);
    return mesh;
}

function createSlabLines(x_start, x_end, isLast) {
    const group = new THREE.Group();
    // Left vertical front
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(x_start, 0, 0),
        new THREE.Vector3(x_start, f(x_start), 0)
    ]), lineMat));
    // Transverse line on top (left)
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(x_start, f(x_start), 0),
        new THREE.Vector3(x_start, f(x_start), -D)
    ]), lineMat));

    // Top curves
    const curvePtsFront = [];
    const curvePtsBack = [];
    const steps = 10;
    for(let i=0; i<=steps; i++) {
        const x = x_start + (i/steps)*(x_end - x_start);
        curvePtsFront.push(new THREE.Vector3(x, f(x), 0));
        curvePtsBack.push(new THREE.Vector3(x, f(x), -D));
    }
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curvePtsFront), lineMat));
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curvePtsBack), lineMat));

    if (isLast) {
        // Right vertical front
        group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(x_end, 0, 0),
            new THREE.Vector3(x_end, f(x_end), 0)
        ]), lineMat));
        // Right transverse top
        group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(x_end, f(x_end), 0),
            new THREE.Vector3(x_end, f(x_end), -D)
        ]), lineMat));
        // Right vertical back
        group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(x_end, 0, -D),
            new THREE.Vector3(x_end, f(x_end), -D)
        ]), lineMat));
    }
    return group;
}

function createIsolatedCrossSection(x_k) {
    const group = new THREE.Group();
    const height = f(x_k);

    const geom = new THREE.PlaneGeometry(D, height);
    geom.rotateY(Math.PI / 2);
    geom.translate(x_k, height / 2, -D / 2);
    const mesh = new THREE.Mesh(geom, matCrossSection);
    group.add(mesh);

    const rad = 0.035;
    const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
    const g1 = new THREE.CylinderGeometry(rad, rad, height, 8);
    const m1 = new THREE.Mesh(g1, mat);
    m1.position.set(x_k, height/2, 0);
    const g2 = new THREE.CylinderGeometry(rad, rad, height, 8);
    const m2 = new THREE.Mesh(g2, mat);
    m2.position.set(x_k, height/2, -D);
    const g3 = new THREE.CylinderGeometry(rad, rad, D, 8);
    const m3 = new THREE.Mesh(g3, mat);
    m3.rotation.x = Math.PI/2;
    m3.position.set(x_k, height, -D/2);
    const g4 = new THREE.CylinderGeometry(rad, rad, D, 8);
    const m4 = new THREE.Mesh(g4, mat);
    m4.rotation.x = Math.PI/2;
    m4.position.set(x_k, 0, -D/2);

    group.add(m1, m2, m3, m4);

    const dotG = new THREE.SphereGeometry(0.08, 16, 16);
    const dot = new THREE.Mesh(dotG, mat);
    dot.position.set(x_k, 0, 0);
    group.add(dot);

    return group;
}

function updateFigure() {
    const n = parseInt(document.getElementById('numSlabs').value);
    let pos = parseFloat(document.getElementById('slicePosition').value);
    const view = document.getElementById('view').value;
    const isIsolated = (view === 'Isolated Slab');

    disposeGroup(slabsGroup);
    disposeGroup(linesGroup);
    disposeGroup(isolatedGroup);
    disposeGroup(ticksGroup);

    const dx = (b - a) / n;
    let k = Math.floor((pos - a) / dx);
    if (k >= n) k = n - 1;
    if (k < 0) k = 0;
    const x_k_star = pos; 

    tickLabels.forEach(lbl => lbl.pos.set(0, -1000, 0));
    lbl_S1.pos.set(0, -1000, 0);
    lbl_S2.pos.set(0, -1000, 0);
    lbl_Sn.pos.set(0, -1000, 0);
    lbl_S.pos.set(0, -1000, 0);
    lbl_xk.pos.set(0, -1000, 0);
    lbl_dxk.pos.set(0, -1000, 0);
    lbl_callout.pos.set(0, -1000, 0);
    arrG.visible = false;
    bracketGroup.visible = false;

    if (!isIsolated) {
        lbl_a.pos.set(a, -0.4, 0);
        lbl_b.pos.set(b, -0.4, 0);

        for(let i=0; i<n; i++) {
            const x0 = a + i*dx;
            const x1 = a + (i+1)*dx;
            const isBlue = (i === k);
            slabsGroup.add(createSlab(x0, x1, isBlue));
            linesGroup.add(createSlabLines(x0, x1, i === n-1));
        }

        // Full solid base outlines
        linesGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a, 0, -D), new THREE.Vector3(b, 0, -D)]), lineMat));
        linesGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a, 0, -D), new THREE.Vector3(a, f(a), -D)]), lineMat));
        linesGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a, 0, 0), new THREE.Vector3(a, 0, -D)]), lineMat));

        // Ticks
        ticksGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a, 0.1, 0), new THREE.Vector3(a, -0.1, 0)]), lineMat));
        ticksGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(b, 0.1, 0), new THREE.Vector3(b, -0.1, 0)]), lineMat));

        if (n === 6) {
            tickLabels[1].div.innerHTML = `<i>x</i><sub>1</sub>`;
            tickLabels[1].pos.set(a + 1*dx, -0.4, 0);
            tickLabels[2].div.innerHTML = `<i>x</i><sub>2</sub>`;
            tickLabels[2].pos.set(a + 2*dx, -0.4, 0);
            tickLabels[3].div.innerHTML = `...`;
            tickLabels[3].pos.set(a + 3.5*dx, -0.4, 0);
            tickLabels[4].div.innerHTML = `<i>x<sub>n-1</sub></i>`;
            tickLabels[4].pos.set(a + 5*dx, -0.4, 0);

            [1, 2, 5].forEach(i => {
                const x = a + i*dx;
                ticksGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x, 0.1, 0), new THREE.Vector3(x, -0.1, 0)]), lineMat));
            });

            lbl_S1.pos.set(a + 0.5*dx, f(a + 0.5*dx)/2, 0.1);
            lbl_S2.pos.set(a + 1.5*dx, f(a + 1.5*dx)/2, 0.1);
            lbl_Sn.pos.set(a + 5.5*dx, f(a + 5.5*dx)/2, 0.1);
            lbl_S.pos.set((a+b)/2, f((a+b)/2) + 0.4, -D/2);
        } else {
            lbl_S.pos.set((a+b)/2, f((a+b)/2) + 0.4, -D/2);
        }
    } else {
        const x0 = a + k*dx;
        const x1 = a + (k+1)*dx;

        slabsGroup.add(createSlab(x0, x1, true));
        linesGroup.add(createSlabLines(x0, x1, true));

        const extraLines = new THREE.Group();
        extraLines.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x0, 0, -D), new THREE.Vector3(x0, f(x0), -D)]), lineMat));
        extraLines.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x0, 0, 0), new THREE.Vector3(x1, 0, 0)]), lineMat));
        extraLines.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x0, 0, -D), new THREE.Vector3(x1, 0, -D)]), lineMat));
        extraLines.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x0, 0, 0), new THREE.Vector3(x0, 0, -D)]), lineMat));
        extraLines.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x1, 0, 0), new THREE.Vector3(x1, 0, -D)]), lineMat));
        linesGroup.add(extraLines);

        isolatedGroup.add(createIsolatedCrossSection(x_k_star));
        lbl_xk.pos.set(x_k_star, -0.15, 0);

        v1.geometry.setFromPoints([new THREE.Vector3(x0, -0.1, 0), new THREE.Vector3(x0, -0.8, 0)]);
        v2.geometry.setFromPoints([new THREE.Vector3(x1, -0.1, 0), new THREE.Vector3(x1, -0.8, 0)]);
        hBracket.geometry.setFromPoints([new THREE.Vector3(x0, -0.5, 0), new THREE.Vector3(x1, -0.5, 0)]);
        bracketGroup.visible = true;
        lbl_dxk.pos.set((x0 + x1)/2, -0.5, 0);

        arrG.visible = true;
        arrG.position.set(x_k_star - 0.2, f(x_k_star)*0.6, -D/2);
        lbl_callout.pos.set(x_k_star - 2.1, f(x_k_star)*0.6 + 0.35, -D/2);

        lbl_a.pos.set(0, -1000, 0);
        lbl_b.pos.set(0, -1000, 0);
    }
}

document.getElementById('numSlabs').addEventListener('input', updateFigure);
document.getElementById('slicePosition').addEventListener('input', updateFigure);
document.getElementById('view').addEventListener('change', updateFigure);

function setActiveBtn(id) {
  ['btnStep1', 'btnStep2', 'btnStep3'].forEach(b => {
    document.getElementById(b).classList.remove('active');
  });
  document.getElementById(id).classList.add('active');
}

document.getElementById('btnStep1').addEventListener('click', () => {
